#!/usr/bin/env bash
set -euo pipefail

mkdir -p keystore

if [ -n "${KEYSTORE_BASE64:-}" ]; then
  echo "Setting up keystore from KEYSTORE_BASE64 secret..."
  printf '%s' "$KEYSTORE_BASE64" | base64 -d > keystore/release.keystore
  cat <<EOF > keystore.properties
storeFile=keystore/release.keystore
storePassword=${KEYSTORE_PASSWORD}
keyAlias=${KEY_ALIAS}
keyPassword=${KEY_PASSWORD}
EOF
else
  echo "Setting up persistent sideload keystore..."
  base64 -d << 'EOF' > keystore/sideload.keystore

EOF
  cat <<EOF > keystore.properties
storeFile=keystore/sideload.keystore
storePassword=kinetica-keyboard
keyAlias=kinetica
keyPassword=kinetica-keyboard
EOF
fi

echo "Keystore setup complete. keystore.properties content:"
cat keystore.properties
